"""Priority product quality rewrite phase 2.
Public SEO only; removes repeated filler paragraphs and adds product-specific depth.
"""
from pathlib import Path
import re

GENERIC_STARTS = [
    'در پروژه‌های حساس، بهتر است پس از نصب و راه‌اندازی، بازخورد واقعی بهره‌بردار',
    'در پروژه‌های حساس، بهتر است قبل از صدور سفارش یک جلسه فنی کوتاه برگزار شود',
]
GENERIC_EXACT = [
    'در ارزیابی نهایی، پیشنهادها باید با جدول TBE مقایسه شوند. استاندارد، متریال، برند، مدارک، زمان تحویل، انحراف‌های فنی، اقلام جانبی و خدمات پس از فروش باید هم‌زمان دیده شوند.',
    'در ارزیابی نهایی، پیشنهادها باید با جدول TBE مقایسه شوند. استاندارد، متریال، برند، مدارک، زمان تحویل، انحراف‌های فنی، اقلام جانبی و خدمات پس از فروش باید هم‌زمان دیده شوند. فقط پس از هم‌سطح‌سازی فنی است که مقایسه قیمت معنا پیدا می‌کند.',
    'در تحویل پروژه، کنترل بسته‌بندی، پلاک، Marking، گواهی‌ها، دستورالعمل نصب و مدارک تست ضروری است. اگر این موارد از ابتدا در RFQ نیاید، اختلاف‌ها معمولاً در نصب یا راه‌اندازی ظاهر می‌شوند.',
]

def visible(s):
    return re.sub(r'\s+',' ', re.sub(r'<[^>]+>',' ',s)).strip()

def clean(html):
    def repl(m):
        t = visible(m.group(1))
        if any(t.startswith(x) for x in GENERIC_STARTS) or t in GENERIC_EXACT:
            return ''
        return m.group(0)
    return re.sub(r'<p\b[^>]*>([\s\S]*?)</p>', repl, html)

